<?php require_once __DIR__.'/../includes/layout.php';require_once __DIR__.'/../includes/widgets.php';require_once __DIR__.'/../includes/calendar_view.php';$u=require_role('admin');$stats=all('SELECT e.nombre,COUNT(c.id) total FROM especialidades e LEFT JOIN medicos m ON m.especialidad_id=e.id LEFT JOIN citas c ON c.medico_id=m.id GROUP BY e.id ORDER BY total DESC LIMIT 8');$max=max(array_column($stats,'total')?:[1]);$recent=all('SELECT c.fecha,c.hora,c.estado,p.nombre paciente,m.nombre medico FROM citas c JOIN pacientes pa ON pa.id=c.paciente_id JOIN usuarios p ON p.id=pa.usuario_id JOIN medicos me ON me.id=c.medico_id JOIN usuarios m ON m.id=me.usuario_id ORDER BY c.id DESC LIMIT 7');header_ui('Panel administrativo');?><div class="page-intro"><h2>Todo MiSalud, en un vistazo ✨</h2><p>Administra profesionales, pacientes y actividad de la plataforma.</p></div><div class="stat-grid"><?php stat_card('♙','Pacientes',count_rows('pacientes'));stat_card('✚','Médicos',count_rows('medicos'),'lavender');stat_card('▦','Citas totales',count_rows('citas'),'peach');?></div><div class="uc-shortcuts"><a class="uc-shortcut" href="<?=url('admin/calendario.php')?>">🗓️ Calendario global</a><a class="uc-shortcut" href="<?=url('admin/estadisticas.php')?>">📊 Estadísticas por médico</a><a class="uc-shortcut" href="<?=url('admin/turnos.php')?>">🎟️ Gestionar turnos</a><a class="uc-shortcut" href="<?=url('admin/donaciones.php')?>">💗 Donaciones</a></div><?php calendar_view('admin'); ?><div class="dashboard-grid"><section class="panel"><div class="panel-heading"><h2>Demanda por especialidad</h2></div><?php foreach($stats as $s):?><div class="bar-row"><div><strong><?=e($s['nombre'])?></strong><small><?=$s['total']?> citas</small></div><div class="bar-track"><span style="width:<?=($s['total']/$max)*100?>%"></span></div></div><?php endforeach;?></section><section class="panel"><div class="panel-heading"><h2>Últimas citas</h2></div><?php if(!$recent):empty_state('Sin movimientos','Las nuevas citas aparecerán aquí.');else:foreach($recent as $r):?><div class="appointment-row"><div class="date-square"><strong><?=date('d',strtotime($r['fecha']))?></strong><span><?=date('M',strtotime($r['fecha']))?></span></div><div class="appointment-info"><strong><?=e($r['paciente'])?> · Dr(a). <?=e($r['medico'])?></strong><small><?=ui_time($r['hora'])?> · <?=e($r['estado'])?></small></div></div><?php endforeach;endif;?></section></div><?php footer_ui();?>
